import React from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext';
import Login from './pages/Login';
import ChangerMdp from './pages/ChangerMdp';
import Dashboard from './pages/Dashboard'; // ta page principale

function PrivateRoute({ children }) {
  const { user } = useAuth();
  // Si pas connecté → redirige vers login
  if (!user) return <Navigate to="/login" replace />;
  // Si connecté mais mdp pas encore changé → redirige vers changement mdp
  if (user.mdp_change === 0) return <Navigate to="/changer-mdp" replace />;
  return children;
}

function AppRoutes() {
  return (
    <Routes>
      <Route path="/login"       element={<Login />} />
      <Route path="/changer-mdp" element={<ChangerMdp />} />
      <Route path="/*" element={
        <PrivateRoute>
          <Dashboard />
        </PrivateRoute>
      } />
    </Routes>
  );
}

export default function App() {
  return (
    <AuthProvider>
      <BrowserRouter>
        <AppRoutes />
      </BrowserRouter>
    </AuthProvider>
  );
}
